import dataclasses
import re
from .errors import LexError


@dataclasses.dataclass(frozen=True)
class Token:
    kind: str
    text: str
    value: object
    offset: int


KEYWORDS = {"let", "print", "if", "else", "while", "true", "false", "and", "or", "not"}


def tokenize(src: str) -> list[Token]:
    tokens = []
    i = 0
    while i < len(src):
        if src[i].isspace():
            i += 1
        elif i + 1 < len(src) and src[i:i+2] == "//":
            while i < len(src) and src[i] != "\n":
                i += 1
        elif src[i].isdigit():
            start, offset = i, i
            while i < len(src) and src[i].isdigit():
                i += 1
            if i < len(src) and src[i] == ".":
                i += 1
                if not (i < len(src) and src[i].isdigit()):
                    raise LexError("Invalid float", offset)
                while i < len(src) and src[i].isdigit():
                    i += 1
                if i < len(src) and src[i] in "eE":
                    i += 1
                    if i < len(src) and src[i] in "+-":
                        i += 1
                    if not (i < len(src) and src[i].isdigit()):
                        raise LexError("Invalid exponent", offset)
                    while i < len(src) and src[i].isdigit():
                        i += 1
                text = src[start:i]
                tokens.append(Token("FLOAT", text, float(text), offset))
            else:
                if i < len(src) and src[i] == ".":
                    raise LexError("Invalid float", offset)
                text = src[start:i]
                tokens.append(Token("INT", text, int(text), offset))
        elif src[i] == ".":
            offset = i
            if not (i + 1 < len(src) and src[i + 1].isdigit()):
                raise LexError("Unexpected character", offset)
            i += 1
            start = i - 1
            while i < len(src) and src[i].isdigit():
                i += 1
            if i < len(src) and src[i] in "eE":
                i += 1
                if i < len(src) and src[i] in "+-":
                    i += 1
                if not (i < len(src) and src[i].isdigit()):
                    raise LexError("Invalid exponent", offset)
                while i < len(src) and src[i].isdigit():
                    i += 1
            text = src[start:i]
            tokens.append(Token("FLOAT", text, float(text), offset))
        elif src[i] == '"':
            offset = i
            i += 1
            val = []
            while i < len(src) and src[i] != '"':
                if src[i] == "\n":
                    raise LexError("Unterminated string", offset)
                if src[i] == "\\":
                    if i + 1 >= len(src):
                        raise LexError("Unterminated string", offset)
                    i += 1
                    if src[i] == "n":
                        val.append("\n")
                    elif src[i] == "t":
                        val.append("\t")
                    elif src[i] == '"':
                        val.append('"')
                    elif src[i] == "\\":
                        val.append("\\")
                    else:
                        raise LexError("Invalid escape", offset)
                    i += 1
                else:
                    val.append(src[i])
                    i += 1
            if i >= len(src):
                raise LexError("Unterminated string", offset)
            i += 1
            decoded = "".join(val)
            tokens.append(Token("STRING", decoded, decoded, offset))
        elif src[i].isalpha() or src[i] == "_":
            start, offset = i, i
            while i < len(src) and (src[i].isalnum() or src[i] == "_"):
                i += 1
            text = src[start:i]
            if text in KEYWORDS:
                tokens.append(Token("KEYWORD", text, text, offset))
            else:
                tokens.append(Token("IDENT", text, text, offset))
        elif src[i:i+2] == "==":
            tokens.append(Token("OP", "==", "==", i))
            i += 2
        elif src[i:i+2] == "!=":
            tokens.append(Token("OP", "!=", "!=", i))
            i += 2
        elif src[i:i+2] == "<=":
            tokens.append(Token("OP", "<=", "<=", i))
            i += 2
        elif src[i:i+2] == ">=":
            tokens.append(Token("OP", ">=", ">=", i))
            i += 2
        elif src[i] in "+-*/%(){}=;":
            tokens.append(Token("OP", src[i], src[i], i))
            i += 1
        elif src[i] == "<":
            tokens.append(Token("OP", "<", "<", i))
            i += 1
        elif src[i] == ">":
            tokens.append(Token("OP", ">", ">", i))
            i += 1
        else:
            raise LexError("Unexpected character", i)
    return tokens

from .lexer import tokenize
from .errors import ParseError, LexError


class ASTNode:
    pass


class Program(ASTNode):
    def __init__(self, statements):
        self.statements = statements


class Let(ASTNode):
    def __init__(self, name, value):
        self.name = name
        self.value = value


class Assign(ASTNode):
    def __init__(self, name, value):
        self.name = name
        self.value = value


class Print(ASTNode):
    def __init__(self, expr):
        self.expr = expr


class If(ASTNode):
    def __init__(self, cond, then_branch, else_branch=None):
        self.cond = cond
        self.then_branch = then_branch
        self.else_branch = else_branch


class While(ASTNode):
    def __init__(self, cond, body):
        self.cond = cond
        self.body = body


class Block(ASTNode):
    def __init__(self, statements):
        self.statements = statements


class BinOp(ASTNode):
    def __init__(self, left, op, right):
        self.left = left
        self.op = op
        self.right = right


class UnaryOp(ASTNode):
    def __init__(self, op, operand):
        self.op = op
        self.operand = operand


class Literal(ASTNode):
    def __init__(self, value):
        self.value = value


class Var(ASTNode):
    def __init__(self, name):
        self.name = name


def parse(src: str) -> Program:
    try:
        tokens = tokenize(src)
    except LexError:
        raise
    parser = Parser(tokens)
    return parser.parse_program()


class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self):
        token = self.peek()
        self.pos += 1
        return token

    def expect(self, kind, value=None):
        token = self.peek()
        if not token or token.kind != kind or (value and token.value != value):
            offset = token.offset if token else len(self.src)
            raise ParseError(f"Expected {kind}", token.offset if token else 0)
        return self.consume()

    def parse_program(self):
        statements = []
        while self.peek():
            statements.append(self.parse_statement())
        return Program(statements)

    def parse_statement(self):
        token = self.peek()
        if not token:
            raise ParseError("Unexpected EOF", 0)
        if token.kind == "KEYWORD" and token.value == "let":
            return self.parse_let()
        elif token.kind == "KEYWORD" and token.value == "print":
            return self.parse_print()
        elif token.kind == "KEYWORD" and token.value == "if":
            return self.parse_if()
        elif token.kind == "KEYWORD" and token.value == "while":
            return self.parse_while()
        elif token.kind == "OP" and token.value == "{":
            return self.parse_block()
        elif token.kind == "IDENT":
            return self.parse_assign()
        else:
            raise ParseError("Expected statement", token.offset)

    def parse_let(self):
        let_token = self.expect("KEYWORD", "let")
        name_token = self.expect("IDENT")
        self.expect("OP", "=")
        value = self.parse_expr()
        self.expect("OP", ";")
        return Let(name_token.value, value)

    def parse_assign(self):
        name_token = self.consume()
        self.expect("OP", "=")
        value = self.parse_expr()
        self.expect("OP", ";")
        return Assign(name_token.value, value)

    def parse_print(self):
        self.expect("KEYWORD", "print")
        expr = self.parse_expr()
        self.expect("OP", ";")
        return Print(expr)

    def parse_if(self):
        self.expect("KEYWORD", "if")
        self.expect("OP", "(")
        cond = self.parse_expr()
        self.expect("OP", ")")
        then_branch = self.parse_statement()
        else_branch = None
        if self.peek() and self.peek().kind == "KEYWORD" and self.peek().value == "else":
            self.consume()
            else_branch = self.parse_statement()
        return If(cond, then_branch, else_branch)

    def parse_while(self):
        self.expect("KEYWORD", "while")
        self.expect("OP", "(")
        cond = self.parse_expr()
        self.expect("OP", ")")
        body = self.parse_statement()
        return While(cond, body)

    def parse_block(self):
        self.expect("OP", "{")
        statements = []
        while self.peek() and not (self.peek().kind == "OP" and self.peek().value == "}"):
            statements.append(self.parse_statement())
        self.expect("OP", "}")
        return Block(statements)

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self.peek() and self.peek().kind == "KEYWORD" and self.peek().value == "or":
            self.consume()
            right = self.parse_and()
            left = BinOp(left, "or", right)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.peek() and self.peek().kind == "KEYWORD" and self.peek().value == "and":
            self.consume()
            right = self.parse_not()
            left = BinOp(left, "and", right)
        return left

    def parse_not(self):
        if self.peek() and self.peek().kind == "KEYWORD" and self.peek().value == "not":
            self.consume()
            return UnaryOp("not", self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_additive()
        token = self.peek()
        if token and token.kind == "OP" and token.value in ["==", "!=", "<", "<=", ">", ">="]:
            op_token = self.consume()
            right = self.parse_additive()
            left = BinOp(left, op_token.value, right)
            if self.peek() and self.peek().kind == "OP" and self.peek().value in ["==", "!=", "<", "<=", ">", ">="]:
                raise ParseError("Comparison is not associative", self.peek().offset)
        return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.peek() and self.peek().kind == "OP" and self.peek().value in ["+", "-"]:
            op_token = self.consume()
            right = self.parse_multiplicative()
            left = BinOp(left, op_token.value, right)
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while self.peek() and self.peek().kind == "OP" and self.peek().value in ["*", "/", "%"]:
            op_token = self.consume()
            right = self.parse_unary()
            left = BinOp(left, op_token.value, right)
        return left

    def parse_unary(self):
        if self.peek() and self.peek().kind == "OP" and self.peek().value == "-":
            self.consume()
            return UnaryOp("-", self.parse_unary())
        return self.parse_primary()

    def parse_primary(self):
        token = self.peek()
        if not token:
            raise ParseError("Unexpected EOF", 0)
        if token.kind == "INT":
            self.consume()
            return Literal(token.value)
        elif token.kind == "FLOAT":
            self.consume()
            return Literal(token.value)
        elif token.kind == "STRING":
            self.consume()
            return Literal(token.value)
        elif token.kind == "KEYWORD" and token.value == "true":
            self.consume()
            return Literal(True)
        elif token.kind == "KEYWORD" and token.value == "false":
            self.consume()
            return Literal(False)
        elif token.kind == "IDENT":
            self.consume()
            return Var(token.value)
        elif token.kind == "OP" and token.value == "(":
            self.consume()
            expr = self.parse_expr()
            self.expect("OP", ")")
            return expr
        else:
            raise ParseError("Expected primary", token.offset)

import dataclasses
from .parser import parse, Let, Assign, Print, If, While, Block, BinOp, UnaryOp, Literal, Var
from .errors import CompileError
from .opcodes import OPCODE_NUMBERS


@dataclasses.dataclass(frozen=True)
class Instr:
    op: str
    arg: int | None


@dataclasses.dataclass
class Program:
    constants: list
    names: list[str]
    instructions: list


class Compiler:
    def __init__(self):
        self.constants = {}
        self.const_list = []
        self.names = {}
        self.declared_names = {}
        self.name_list = []
        self.instructions = []

    def const_index(self, val):
        key = (type(val).__name__, val)
        if key not in self.constants:
            self.constants[key] = len(self.const_list)
            self.const_list.append(val)
        return self.constants[key]

    def add_instr(self, op: str, arg: int | None = None) -> int:
        self.instructions.append(Instr(op, arg))
        return len(self.instructions) - 1

    def compile_source(self, src: str, optimize: bool = False) -> Program:
        ast = parse(src)
        if optimize:
            from .optimizer import fold_constants
            ast = fold_constants(ast)
        self.compile_program(ast)
        self.add_instr("HALT")
        return Program(self.const_list, self.name_list, self.instructions)

    def compile_program(self, node):
        for stmt in node.statements:
            self.compile_statement(stmt)

    def compile_statement(self, node):
        if isinstance(node, Let):
            if node.name in self.declared_names:
                raise CompileError(f"Variable '{node.name}' already declared")
            self.declared_names[node.name] = len(self.name_list)
            self.name_list.append(node.name)
            self.names[node.name] = len(self.name_list) - 1
            self.compile_expr(node.value)
            self.add_instr("STORE", self.names[node.name])
        elif isinstance(node, Assign):
            if node.name not in self.declared_names:
                raise CompileError(f"Variable '{node.name}' not declared")
            self.compile_expr(node.value)
            self.add_instr("STORE", self.names[node.name])
        elif isinstance(node, Print):
            self.compile_expr(node.expr)
            self.add_instr("PRINT")
        elif isinstance(node, If):
            self.compile_expr(node.cond)
            jump_false = self.add_instr("JUMP_IF_FALSE", 0)
            self.compile_statement(node.then_branch)
            if node.else_branch:
                jump_end = self.add_instr("JUMP", 0)
                self.instructions[jump_false].arg = len(self.instructions)
                self.compile_statement(node.else_branch)
                self.instructions[jump_end].arg = len(self.instructions)
            else:
                self.instructions[jump_false].arg = len(self.instructions)
        elif isinstance(node, While):
            loop_start = len(self.instructions)
            self.compile_expr(node.cond)
            jump_exit = self.add_instr("JUMP_IF_FALSE", 0)
            self.compile_statement(node.body)
            self.add_instr("JUMP", loop_start)
            self.instructions[jump_exit].arg = len(self.instructions)
        elif isinstance(node, Block):
            for stmt in node.statements:
                self.compile_statement(stmt)

    def compile_expr(self, node):
        if isinstance(node, Literal):
            idx = self.const_index(node.value)
            self.add_instr("CONST", idx)
        elif isinstance(node, Var):
            if node.name not in self.declared_names:
                raise CompileError(f"Variable '{node.name}' not declared")
            self.add_instr("LOAD", self.names[node.name])
        elif isinstance(node, BinOp):
            if node.op == "and":
                self.compile_expr(node.left)
                jump_false = self.add_instr("JUMP_IF_FALSE", 0)
                self.add_instr("POP")
                self.compile_expr(node.right)
                self.instructions[jump_false].arg = len(self.instructions)
            elif node.op == "or":
                self.compile_expr(node.left)
                jump_true = self.add_instr("JUMP_IF_FALSE", 0)
                jump_end = self.add_instr("JUMP", 0)
                self.instructions[jump_true].arg = len(self.instructions)
                self.add_instr("POP")
                self.compile_expr(node.right)
                self.instructions[jump_end].arg = len(self.instructions)
            else:
                self.compile_expr(node.left)
                self.compile_expr(node.right)
                op_map = {"+": "ADD", "-": "SUB", "*": "MUL", "/": "DIV", "%": "MOD",
                          "==": "EQ", "!=": "NE", "<": "LT", "<=": "LE", ">": "GT", ">=": "GE"}
                self.add_instr(op_map[node.op])
        elif isinstance(node, UnaryOp):
            self.compile_expr(node.operand)
            if node.op == "-":
                self.add_instr("NEG")
            elif node.op == "not":
                self.add_instr("NOT")


def compile_source(src: str, *, optimize: bool = False) -> Program:
    return Compiler().compile_source(src, optimize)

from .parser import Literal, BinOp, UnaryOp, Var, Let, Assign, Print, If, While, Block


def fold_constants(node):
    if isinstance(node, Literal):
        return node
    elif isinstance(node, Var):
        return node
    elif isinstance(node, UnaryOp):
        operand = fold_constants(node.operand)
        if isinstance(operand, Literal):
            if node.op == "-":
                if isinstance(operand.value, (int, float)):
                    return Literal(-operand.value)
            elif node.op == "not":
                if isinstance(operand.value, bool):
                    return Literal(not operand.value)
        return UnaryOp(node.op, operand)
    elif isinstance(node, BinOp):
        left = fold_constants(node.left)
        right = fold_constants(node.right)
        if isinstance(left, Literal) and isinstance(right, Literal):
            lv, rv = left.value, right.value
            try:
                if node.op == "+":
                    if isinstance(lv, str) and isinstance(rv, str):
                        return Literal(lv + rv)
                    if isinstance(lv, (int, float)) and isinstance(rv, (int, float)):
                        result = lv + rv
                        return Literal(result)
                elif node.op == "-" and isinstance(lv, (int, float)) and isinstance(rv, (int, float)):
                    return Literal(lv - rv)
                elif node.op == "*" and isinstance(lv, (int, float)) and isinstance(rv, (int, float)):
                    return Literal(lv * rv)
                elif node.op == "/" and isinstance(lv, (int, float)) and isinstance(rv, (int, float)):
                    if rv == 0:
                        return BinOp(left, node.op, right)
                    return Literal(lv / rv)
                elif node.op == "%" and isinstance(lv, int) and isinstance(rv, int):
                    if rv == 0:
                        return BinOp(left, node.op, right)
                    return Literal(lv % rv)
                elif node.op == "==":
                    return Literal(lv == rv)
                elif node.op == "!=":
                    return Literal(lv != rv)
                elif node.op == "<":
                    if isinstance(lv, (int, float)) and isinstance(rv, (int, float)):
                        return Literal(lv < rv)
                    if isinstance(lv, str) and isinstance(rv, str):
                        return Literal(lv < rv)
                    return BinOp(left, node.op, right)
                elif node.op == "<=":
                    if isinstance(lv, (int, float)) and isinstance(rv, (int, float)):
                        return Literal(lv <= rv)
                    if isinstance(lv, str) and isinstance(rv, str):
                        return Literal(lv <= rv)
                    return BinOp(left, node.op, right)
                elif node.op == ">":
                    if isinstance(lv, (int, float)) and isinstance(rv, (int, float)):
                        return Literal(lv > rv)
                    if isinstance(lv, str) and isinstance(rv, str):
                        return Literal(lv > rv)
                    return BinOp(left, node.op, right)
                elif node.op == ">=":
                    if isinstance(lv, (int, float)) and isinstance(rv, (int, float)):
                        return Literal(lv >= rv)
                    if isinstance(lv, str) and isinstance(rv, str):
                        return Literal(lv >= rv)
                    return BinOp(left, node.op, right)
                elif node.op == "and":
                    if isinstance(lv, bool) and isinstance(rv, bool):
                        return Literal(lv and rv)
                elif node.op == "or":
                    if isinstance(lv, bool) and isinstance(rv, bool):
                        return Literal(lv or rv)
            except Exception:
                pass
        if isinstance(left, Literal) and left.value is False and node.op == "and":
            return Literal(False)
        if isinstance(left, Literal) and left.value is True and node.op == "or":
            return Literal(True)
        return BinOp(left, node.op, right)
    elif isinstance(node, Let):
        return Let(node.name, fold_constants(node.value))
    elif isinstance(node, Assign):
        return Assign(node.name, fold_constants(node.value))
    elif isinstance(node, Print):
        return Print(fold_constants(node.expr))
    elif isinstance(node, If):
        return If(fold_constants(node.cond), fold_constants(node.then_branch),
                  fold_constants(node.else_branch) if node.else_branch else None)
    elif isinstance(node, While):
        return While(fold_constants(node.cond), fold_constants(node.body))
    elif isinstance(node, Block):
        return Block([fold_constants(stmt) for stmt in node.statements])
    else:
        return node

from .compiler import Program
from .errors import VMRuntimeError, StepLimitError


def execute(program: Program, *, step_limit: int = 100_000) -> list[str]:
    if not isinstance(step_limit, int) or step_limit <= 0 or isinstance(step_limit, bool):
        raise ValueError("step_limit must be a positive integer")
    vm = VM(program, step_limit)
    return vm.run()


class VM:
    def __init__(self, program: Program, step_limit: int):
        self.program = program
        self.step_limit = step_limit
        self.pc = 0
        self.stack = []
        self.variables = [None] * len(program.names)
        self.assigned = [False] * len(program.names)
        self.steps = 0
        self.output = []

    def run(self) -> list[str]:
        while self.pc < len(self.program.instructions):
            if self.steps > self.step_limit:
                raise StepLimitError("Step limit exceeded")
            self.steps += 1
            instr = self.program.instructions[self.pc]
            self.execute_instr(instr)
            self.pc += 1
        return self.output

    def execute_instr(self, instr):
        if instr.op == "CONST":
            self.stack.append(self.program.constants[instr.arg])
        elif instr.op == "LOAD":
            if not self.assigned[instr.arg]:
                raise VMRuntimeError(f"Variable '{self.program.names[instr.arg]}' not assigned")
            self.stack.append(self.variables[instr.arg])
        elif instr.op == "STORE":
            val = self.stack.pop()
            self.variables[instr.arg] = val
            self.assigned[instr.arg] = True
        elif instr.op == "ADD":
            right = self.stack.pop()
            left = self.stack.pop()
            if isinstance(left, str) and isinstance(right, str):
                self.stack.append(left + right)
            elif isinstance(left, bool) or isinstance(right, bool):
                raise VMRuntimeError("Cannot add bool")
            elif isinstance(left, (int, float)) and isinstance(right, (int, float)):
                result = left + right
                self.stack.append(result)
            else:
                raise VMRuntimeError("Type error in +")
        elif instr.op == "SUB":
            right = self.stack.pop()
            left = self.stack.pop()
            if isinstance(left, bool) or isinstance(right, bool):
