import struct
import zlib
from .compiler import Program, Instr
from .errors import SerializationError
from .opcodes import OPCODE_NUMBERS


def dumps(program: Program) -> bytes:
    data = bytearray()
    data.extend(b"MVM1")
    data.append(1)

    data.extend(struct.pack(">H", len(program.names)))
    for name in program.names:
        name_bytes = name.encode("utf-8")
        data.extend(struct.pack(">H", len(name_bytes)))
        data.extend(name_bytes)

    data.extend(struct.pack(">H", len(program.constants)))
    for const in program.constants:
        if isinstance(const, int):
            if const < -(2**63) or const >= 2**63:
                raise SerializationError("INT constant out of range")
            data.append(0x01)
            data.extend(struct.pack(">q", const))
        elif isinstance(const, float):
            data.append(0x02)
            data.extend(struct.pack(">d", const))
        elif isinstance(const, str):
            data.append(0x03)
            const_bytes = const.encode("utf-8")
            data.extend(struct.pack(">I", len(const_bytes)))
            data.extend(const_bytes)
        elif isinstance(const, bool):
            data.append(0x04)
            data.append(1 if const else 0)

    data.extend(struct.pack(">I", len(program.instructions)))
    for instr in program.instructions:
        op_num = OPCODE_NUMBERS[instr.op]
        data.append(op_num)
        arg = 0xFFFFFFFF if instr.arg is None else instr.arg
        data.extend(struct.pack(">I", arg))

    checksum = zlib.crc32(data) & 0xFFFFFFFF
    data.extend(struct.pack(">I", checksum))
    return bytes(data)


def loads(data: bytes) -> Program:
    if len(data) < 4:
        raise SerializationError("Truncated file")
    if data[:4] != b"MVM1":
        raise SerializationError("Bad magic")

    pos = 4
    if pos >= len(data):
        raise SerializationError("Truncated file")
    version = data[pos]
    pos += 1
    if version != 1:
        raise SerializationError("Unsupported version")

    if pos + 2 > len(data):
        raise SerializationError("Truncated file")
    name_count = struct.unpack(">H", data[pos:pos+2])[0]
    pos += 2

    names = []
    for _ in range(name_count):
        if pos + 2 > len(data):
            raise SerializationError("Truncated file")
        name_len = struct.unpack(">H", data[pos:pos+2])[0]
        pos += 2
        if pos + name_len > len(data):
            raise SerializationError("Truncated file")
        names.append(data[pos:pos+name_len].decode("utf-8"))
        pos += name_len

    if pos + 2 > len(data):
        raise SerializationError("Truncated file")
    const_count = struct.unpack(">H", data[pos:pos+2])[0]
    pos += 2

    constants = []
    for _ in range(const_count):
        if pos >= len(data):
            raise SerializationError("Truncated file")
        tag = data[pos]
        pos += 1
        if tag == 0x01:
            if pos + 8 > len(data):
                raise SerializationError("Truncated file")
            const_val = struct.unpack(">q", data[pos:pos+8])[0]
            pos += 8
            constants.append(const_val)
        elif tag == 0x02:
            if pos + 8 > len(data):
                raise SerializationError("Truncated file")
            const_val = struct.unpack(">d", data[pos:pos+8])[0]
            pos += 8
            constants.append(const_val)
        elif tag == 0x03:
            if pos + 4 > len(data):
                raise SerializationError("Truncated file")
            str_len = struct.unpack(">I", data[pos:pos+4])[0]
            pos += 4
            if pos + str_len > len(data):
                raise SerializationError("Truncated file")
            const_val = data[pos:pos+str_len].decode("utf-8")
            pos += str_len
            constants.append(const_val)
        elif tag == 0x04:
            if pos >= len(data):
                raise SerializationError("Truncated file")
            bool_val = data[pos]
            pos += 1
            if bool_val not in (0, 1):
                raise SerializationError("Invalid bool value")
            constants.append(bool(bool_val))
        else:
            raise SerializationError("Unknown constant tag")

    if pos + 4 > len(data):
        raise SerializationError("Truncated file")
    instr_count = struct.unpack(">I", data[pos:pos+4])[0]
    pos += 4

    if pos + 4 > len(data):
        raise SerializationError("Truncated file")
    stored_checksum_pos = pos + instr_count * 5
    if stored_checksum_pos + 4 > len(data):
        raise SerializationError("Truncated file")
    stored_checksum = struct.unpack(">I", data[stored_checksum_pos:stored_checksum_pos+4])[0]

    calc_checksum = zlib.crc32(data[:stored_checksum_pos]) & 0xFFFFFFFF
    if calc_checksum != stored_checksum:
        raise SerializationError("Checksum mismatch")

    instructions = []
    for _ in range(instr_count):
        if pos >= len(data):
            raise SerializationError("Truncated file")
        op_num = data[pos]
        pos += 1
        if pos + 4 > len(data):
            raise SerializationError("Truncated file")
        arg = struct.unpack(">I", data[pos:pos+4])[0]
        pos += 4

        op_name = None
        for name, num in OPCODE_NUMBERS.items():
            if num == op_num:
                op_name = name
                break
        if op_name is None:
            raise SerializationError("Unknown opcode")

        if arg == 0xFFFFFFFF:
            instructions.append(Instr(op_name, None))
        else:
            instructions.append(Instr(op_name, arg))

    if pos != stored_checksum_pos:
        raise SerializationError("Instruction count mismatch")

    if len(data) != stored_checksum_pos + 4:
        raise SerializationError("Trailing bytes")

    return Program(constants, names, instructions)

from .compiler import Program


def disassemble(program: Program) -> str:
    lines = []
    for idx, instr in enumerate(program.instructions):
        line = f"{idx:04d} {instr.op}"
        if instr.arg is not None:
            line += f" {instr.arg}"
        if instr.op == "CONST":
            const = program.constants[instr.arg]
            const_str = format_const(const)
            line += f"  ; {const_str}"
        line += "\n"
        lines.append(line)
    return "".join(lines)


def format_const(val):
    if isinstance(val, bool):
        return "true" if val else "false"
    elif isinstance(val, str):
        escaped = val.replace("\\", "\\\\").replace("\n", "\\n").replace("\t", "\\t").replace('"', '\\"')
        return f'"{escaped}"'
    else:
        return str(val)

import sys
import argparse
from . import compile_source, execute, dumps, loads, disassemble
from .errors import MicroVMError


def main(argv=None):
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest="command")

    run_parser = subparsers.add_parser("run")
    run_parser.add_argument("file")
    run_parser.add_argument("--optimize", action="store_true")
    run_parser.add_argument("--step-limit", type=int, default=100_000)

    build_parser = subparsers.add_parser("build")
    build_parser.add_argument("file")
    build_parser.add_argument("out")
    build_parser.add_argument("--optimize", action="store_true")

    exec_parser = subparsers.add_parser("exec")
    exec_parser.add_argument("file")
    exec_parser.add_argument("--step-limit", type=int, default=100_000)

    disasm_parser = subparsers.add_parser("disasm")
    disasm_parser.add_argument("file")

    try:
        args = parser.parse_args(argv)
    except SystemExit:
        return 2

    if args.command is None:
        parser.print_help()
        return 2

    try:
        if args.command == "run":
            try:
                with open(args.file, "r") as f:
                    src = f.read()
            except Exception:
                return 2
            if args.step_limit <= 0 or not isinstance(args.step_limit, int):
                return 2
            try:
                prog = compile_source(src, optimize=args.optimize)
                output = execute(prog, step_limit=args.step_limit)
                for line in output:
                    print(line)
                return 0
            except MicroVMError as e:
                print(str(e), file=sys.stderr)
                return 3
        elif args.command == "build":
            try:
                with open(args.file, "r") as f:
                    src = f.read()
            except Exception:
                return 2
            try:
                prog = compile_source(src, optimize=args.optimize)
                data = dumps(prog)
                with open(args.out, "wb") as f:
                    f.write(data)
                return 0
            except MicroVMError as e:
                print(str(e), file=sys.stderr)
                return 3
        elif args.command == "exec":
            try:
                with open(args.file, "rb") as f:
                    data = f.read()
            except Exception:
                return 2
            if args.step_limit <= 0 or not isinstance(args.step_limit, int):
                return 2
            try:
                prog = loads(data)
                output = execute(prog, step_limit=args.step_limit)
                for line in output:
                    print(line)
                return 0
            except MicroVMError as e:
                print(str(e), file=sys.stderr)
                return 3
        elif args.command == "disasm":
            try:
                with open(args.file, "rb") as f:
                    data = f.read()
            except Exception:
                return 2
            try:
                prog = loads(data)
                output = disassemble(prog)
                print(output, end="")
                return 0
            except MicroVMError as e:
                print(str(e), file=sys.stderr)
                return 3
    except Exception as e:
        print(str(e), file=sys.stderr)
        return 3

    return 2


if __name__ == "__main__":
    sys.exit(main())

