def _validate_header(data: bytes) -> int:
    if len(data) < 5:
        raise SerializationError("Truncated file")
    if data[:4] != b"MVM1":
        raise SerializationError("Bad magic")
    if data[4] != 1:
        raise SerializationError("Unsupported version")
    return 5


def _load_header_and_names(data: bytes, pos: int) -> tuple[list[str], int]:
    if pos + 2 > len(data):
        raise SerializationError("Truncated file")
    name_count = struct.unpack(">H", data[pos:pos+2])[0]
    pos += 2
    names = []
    for _ in range(name_count):
        if pos + 2 > len(data):
            raise SerializationError("Truncated file")
        name_len = struct.unpack(">H", data[pos:pos+2])[0]
        pos += 2
        if pos + name_len > len(data):
            raise SerializationError("Truncated file")
        names.append(data[pos:pos+name_len].decode("utf-8"))
        pos += name_len
    return names, pos


def _validate_and_load_instructions(data: bytes, pos: int, instr_count: int,
                                    stored_checksum_pos: int) -> list:
    instructions = []
    for _ in range(instr_count):
        if pos >= len(data):
            raise SerializationError("Truncated file")
        op_num = data[pos]
        pos += 1
        if pos + 4 > len(data):
            raise SerializationError("Truncated file")
        arg = struct.unpack(">I", data[pos:pos+4])[0]
        pos += 4
        op_name = None
        for name, num in OPCODE_NUMBERS.items():
            if num == op_num:
                op_name = name
                break
        if op_name is None:
            raise SerializationError("Unknown opcode")
        instructions.append(Instr(op_name, None if arg == 0xFFFFFFFF else arg))
    if pos != stored_checksum_pos:
        raise SerializationError("Instruction count mismatch")
    return instructions


def loads(data: bytes) -> Program:
    pos = _validate_header(data)
    names, pos = _load_header_and_names(data, pos)
    constants, pos = _load_constants(data, pos)
    if pos + 4 > len(data):
        raise SerializationError("Truncated file")
    instr_count = struct.unpack(">I", data[pos:pos+4])[0]
    pos += 4
    stored_checksum_pos = pos + instr_count * 5
